var n=`0622-mechouia-salad`;var t=`world-0622`;var a=`TN`;var s=`northern-africa`;var o=4;var r=48;var l={en:`Mechouia Salad`,ua:`Салат мешуїя`};var d={en:`Mechouia Salad is a Tunisia classic prepared with red bell pepper, tomato, yellow onion, garlic. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Салат мешуїя, страва кухні країни Туніс зі складниками: червоний солодкий перець, помідор, жовта цибуля, часник. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Cut the vegetables evenly and roast at 200°C for about 28 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 28 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:28,i:[[`red-bell-pepper`,430,`g`],[`tomato`,470,`g`],[`yellow-onion`,160,`g`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`garlic`,3,`clove`],[`scotch-bonnet-pepper`,1,`pcs`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:6,i:[[`extra-virgin-olive-oil`,55,`ml`],[`lemon-juice`,35,`ml`],[`ground-cumin`,4,`g`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`black-olives`,75,`g`],[`canned-tuna`,130,`g`]]}];var c={slug:n,id:t,country:`TN`,region:s,servings:4,minutes:48,title:l,text:d,steps:g};export{a as country,c as default,t as id,r as minutes,s as region,o as servings,n as slug,g as steps,d as text,l as title};